@startuml

class SensorController {
  + controllerID : string
  + systemName : string
}

class Apartment {
  + address : string
}

class Room {
  + description : string
}

abstract class Sensor {
  + vendorID : string
  + description : string
  + unit : Unit
}

class TemperatureSensor {
  + minValue : double
  + maxValue : double
}

class PowerSensor {
  + totalConsumption : double
}

class Inhabitant {
  + username : string
  + password : string
}

class MeasuredValue {
  + timestamp : datetime
  + value : double
}

enum Unit {
  CELSIUS
  WATT
}

class EMonitor {
  + systemID : string
}

class AlertMessage {
  + content : string
}

SensorController "1" *-- "1" Apartment
Apartment "1" *-- "2..*" Room
Room "1" *-- "1..*" Sensor
Sensor "1" *-- "1..*" MeasuredValue
Sensor "1" *-- "0..1" MeasuredValue : lastValue
Inhabitant "*" -- "1" Apartment
Inhabitant "0..1" -- "1" SensorController : logsOn
Inhabitant "0..1" -- "1" Sensor : setsThreshold
Inhabitant "0..1" -- "1" Sensor : configures
SensorController "1" -- "1" EMonitor
EMonitor "1" -- "1..*" Sensor : checksThreshold
EMonitor "1" -- "0..*" AlertMessage
AlertMessage "1" -- "1" Apartment : sentTo

TemperatureSensor --|> Sensor
PowerSensor --|> Sensor

@enduml

